/** RAG data structures. Vectors are not part of Document; they are generated by MilvusStore at write time. */

export type ChunkContentType = "page_intro" | "content" | "outline" | "summary";

export interface Chunk {
  /** Display text */
  displayText: string;
  /** Text sent for embedding (with title prefix) */
  embeddingText: string;
  sectionTitle: string;
  contentType: ChunkContentType;
  charStart: number;
  charEnd: number;
}

/** bilibili video-level metadata */
export interface VideoContent {
  bvid: string;
  cid?: number;
  title: string;
  source?: string;
  url?: string;
  content: string;
  outline?: string;
}

/** Document returned after retrieval (chunk + metadata + score) */
export interface Document {
  text: string;
  score?: number;
  rerankScore?: number;
  metadata: DocumentMetadata;
}

export interface DocumentMetadata {
  bvid?: string;
  cid?: number;
  pageIndex?: number;
  chunkIndex?: number;
  chunkId: string;
  title?: string;
  pageTitle?: string;
  source?: string;
  sectionTitle?: string;
  contentType?: string;
  url?: string;
  /** Cloud-drive dimensions */
  uploadUuid?: string;
  uid?: string;
  sourceType?: string;
}

/** Retrieval filter scope (mirrors the scope param of Python search) */
export interface RagFilter {
  bvids?: string[];
  uploadUuids?: string[];
  uid?: string;
  workspacePages?: Array<{ bvid: string; pageIndex: number }>;
}

export interface CollectionStats {
  collectionName: string;
  totalChunks: number;
  totalVideos: number;
  available: boolean;
  cloudCollectionName: string;
  cloudChunks: number;
  cloudAvailable: boolean;
}
